int cmp(const void *_a, const void *_b) {
  int a = *(int *)_a, b = *(int *)_b;
  return a - b;
}

int largestPerimeter(int *A, int ASize) {
  qsort(A, ASize, sizeof(int), cmp);
  for (int i = ASize - 1; i >= 2; --i) {
    if (A[i - 2] + A[i - 1] > A[i]) {
      return A[i - 2] + A[i - 1] + A[i];
    }
  }
  return 0;
}

